architectureDiagramMermaid:
flowchart TD
    Cron["⏰ macOS Crontab (0 8-23 * * *)"] --> BackupAll["🐚 scripts/backup_all.sh"]
    BackupAll --> CheckDaily{"📅 Backup exists today?"}
    CheckDaily -- Yes --> Skip["⚡ Skip Project (Saves bandwidth)"]
    CheckDaily -- No --> CheckTCP{"🔌 Netcat (nc) TCP OK?"}
    CheckTCP -- Failed --> LogError["⚠️ Log Error / Next cycle"]
    CheckTCP -- OK --> PgDump["🐘 Run pg_dump"]
    PgDump --> CheckDump{"💾 Dump Completed?"}
    CheckDump -- OK --> SuccessClean["✅ Clean > RETENTION_DAYS & Notify"]
    CheckDump -- Error --> Rollback["🗑️ Auto-Cleanup / Delete partial .sql"]
